//! Synthetic data generation for DDoS and scanner training samples.
//!
//! DDoS synthetic samples are generated by sampling from CIC-IDS2017 timing
//! profiles.  Scanner synthetic samples are generated from wordlist paths
//! and realistic browser-like feature vectors.

use crate::dataset::cicids::TimingProfile;
use crate::dataset::sample::{DataSource, TrainingSample};
use crate::ddos::features::NUM_FEATURES;
use crate::scanner::features::NUM_SCANNER_FEATURES;

use anyhow::Result;
use rand::prelude::*;
use rand::rngs::StdRng;
use std::io::BufRead;
use std::path::Path;

/// Configuration for synthetic sample generation.
#[derive(Debug, Clone)]
pub struct SyntheticConfig {
    /// Num ddos attack.
    pub num_ddos_attack: usize,
    /// Num ddos normal.
    pub num_ddos_normal: usize,
    /// Num scanner attack.
    pub num_scanner_attack: usize,
    /// Num scanner normal.
    pub num_scanner_normal: usize,
    /// Seed.
    pub seed: u64,
}

impl Default for SyntheticConfig {
    fn default() -> Self {
        Self {
            num_ddos_attack: 1000,
            num_ddos_normal: 1000,
            num_scanner_attack: 1000,
            num_scanner_normal: 1000,
            seed: 42,
        }
    }
}

/// Generate synthetic DDoS training samples from CIC-IDS2017 timing profiles.
///
/// Produces 14-dimensional feature vectors matching `NUM_FEATURES`:
///   0: request_rate, 1: unique_paths, 2: unique_hosts, 3: error_rate,
///   4: avg_duration_ms, 5: method_entropy, 6: burst_score, 7: path_repetition,
///   8: avg_content_length, 9: unique_user_agents, 10: cookie_ratio,
///   11: referer_ratio, 12: accept_language_ratio, 13: suspicious_path_ratio
pub fn generate_ddos_samples(
    profiles: &[TimingProfile],
    config: &SyntheticConfig,
) -> Vec<TrainingSample> {
    let mut rng = StdRng::seed_from_u64(config.seed);
    let mut samples = Vec::with_capacity(config.num_ddos_attack + config.num_ddos_normal);

    // Generate attack samples.
    for _ in 0..config.num_ddos_attack {
        let features = generate_ddos_attack_features(profiles, &mut rng);
        samples.push(TrainingSample {
            features,
            label: 1.0,
            source: DataSource::SyntheticCicTiming,
            weight: 0.5,
        });
    }

    // Generate normal samples.
    for _ in 0..config.num_ddos_normal {
        let features = generate_ddos_normal_features(&mut rng);
        samples.push(TrainingSample {
            features,
            label: 0.0,
            source: DataSource::SyntheticCicTiming,
            weight: 0.5,
        });
    }

    samples
}

/// Generate a single DDoS attack feature vector, sampling from timing profiles.
fn generate_ddos_attack_features(profiles: &[TimingProfile], rng: &mut StdRng) -> Vec<f32> {
    let mut features = vec![0.0f32; NUM_FEATURES];

    // Sample from a random profile if available, otherwise use defaults.
    let (iat_mean, burst_mean, bps_mean) = if !profiles.is_empty() {
        let profile = &profiles[rng.random_range(0..profiles.len())];
        let iat = sample_positive_normal(
            rng,
            profile.inter_arrival_mean,
            profile.inter_arrival_std,
        );
        let burst = sample_positive_normal(
            rng,
            profile.burst_duration_mean,
            profile.burst_duration_std,
        );
        let bps = sample_positive_normal(
            rng,
            profile.flow_bytes_per_sec_mean,
            profile.flow_bytes_per_sec_std,
        );
        (iat, burst, bps)
    } else {
        // Fallback: aggressive attack defaults.
        let iat = rng.random_range(0.001..0.05);
        let burst = rng.random_range(0.5..5.0);
        let bps = rng.random_range(10000.0..100000.0);
        (iat, burst, bps)
    };

    // Each feature follows an 80% "typical attack" / 20% "stealthy adversary"
    // pattern. The stealthy minority overlaps the legitimate-user range,
    // preventing trivial single-feature separation.
    let stealthy = rng.random_bool(0.2);

    // 0: request_rate — most attacks are high-rate, stealthy minority is slow-and-low.
    features[0] = if stealthy {
        rng.random_range(0.5..30.0) as f32
    } else if iat_mean > 0.0 {
        (1.0 / iat_mean).min(1000.0) as f32
    } else {
        rng.random_range(50.0..500.0) as f32
    };

    // 1: unique_paths — repeat-heavy bots vs scanning bots.
    features[1] = if stealthy {
        rng.random_range(5.0..40.0) as f32
    } else {
        rng.random_range(1.0..10.0) as f32
    };

    // 2: unique_hosts — typically 1 for DDoS, stealthy attackers spread across vhosts.
    features[2] = rng.random_range(1.0..6.0) as f32;

    // 3: error_rate — most attacks miss a lot, stealthy ones target real endpoints.
    features[3] = if stealthy {
        rng.random_range(0.0..0.3) as f32
    } else {
        rng.random_range(0.2..0.9) as f32
    };

    // 4: avg_duration_ms — derived from burst duration; clamp into a realistic band.
    features[4] = (burst_mean * 100.0).clamp(1.0, 5000.0) as f32;

    // 5: method_entropy — most attacks are GET-only, stealthy attackers mix verbs.
    features[5] = if stealthy {
        rng.random_range(0.2..1.2) as f32
    } else {
        rng.random_range(0.0..0.4) as f32
    };

    // 6: burst_score — typical attacks are bursty, stealthy ones are paced.
    features[6] = if stealthy {
        rng.random_range(0.5..15.0) as f32
    } else if iat_mean > 0.0 {
        (1.0 / iat_mean).min(500.0) as f32
    } else {
        rng.random_range(10.0..200.0) as f32
    };

    // 7: path_repetition — typical attacks hammer a path; stealthy ones distribute.
    features[7] = if stealthy {
        rng.random_range(0.1..0.6) as f32
    } else {
        rng.random_range(0.5..1.0) as f32
    };

    // 8: avg_content_length — derived from flow bytes (no overlap shaping; signal lives in tails).
    features[8] = (bps_mean * 0.01).clamp(0.0, 10000.0) as f32;

    // 9: unique_user_agents — typical bots use 1-2 UAs, advanced bots rotate.
    features[9] = if stealthy {
        rng.random_range(3.0..8.0) as f32
    } else {
        rng.random_range(1.0..3.0) as f32
    };

    // 10: cookie_ratio — typical bots send no cookies; stealthy adversaries replay sessions.
    features[10] = if stealthy {
        rng.random_range(0.3..0.9) as f32
    } else {
        rng.random_range(0.0..0.3) as f32
    };

    // 11: referer_ratio — typical bots send no referer; stealthy ones forge headers.
    features[11] = if stealthy {
        rng.random_range(0.2..0.8) as f32
    } else {
        rng.random_range(0.0..0.2) as f32
    };

    // 12: accept_language_ratio — typical bots omit; stealthy ones send realistic headers.
    features[12] = if stealthy {
        rng.random_range(0.3..0.9) as f32
    } else {
        rng.random_range(0.0..0.2) as f32
    };

    // 13: suspicious_path_ratio — typical attacks hit known-bad paths; stealthy ones probe legit endpoints.
    features[13] = if stealthy {
        rng.random_range(0.0..0.2) as f32
    } else {
        rng.random_range(0.1..0.7) as f32
    };

    features
}

/// Generate a single DDoS normal feature vector.
///
/// 80% "typical browser user" / 20% "unusual but legitimate": privacy-mode
/// users, fresh-visit users without cookies, mobile-app traffic, API clients,
/// genuine flash-crowd bursts. The unusual minority overlaps the attack
/// range, preventing single-feature separation.
fn generate_ddos_normal_features(rng: &mut StdRng) -> Vec<f32> {
    let mut features = vec![0.0f32; NUM_FEATURES];
    let unusual = rng.random_bool(0.2);

    // 0: request_rate — typical browsing is light; legitimate bursts (flash crowd, API client) reach attack-range.
    features[0] = if unusual {
        rng.random_range(3.0..60.0) as f32
    } else {
        rng.random_range(0.1..5.0) as f32
    };
    // 1: unique_paths — typical moderate; unusual narrow (single-page app, repeat polling).
    features[1] = if unusual {
        rng.random_range(1.0..8.0) as f32
    } else {
        rng.random_range(3.0..30.0) as f32
    };
    // 2: unique_hosts — typical 1-5; can be 1 for single-host sites.
    features[2] = rng.random_range(1.0..6.0) as f32;
    // 3: error_rate — typical low; some real users hit 404/500 from broken links.
    features[3] = if unusual {
        rng.random_range(0.1..0.4) as f32
    } else {
        rng.random_range(0.0..0.15) as f32
    };
    // 4: avg_duration_ms — reasonable.
    features[4] = rng.random_range(10.0..500.0) as f32;
    // 5: method_entropy — typical moderate; mobile apps often GET-only (entropy ≈ 0).
    features[5] = if unusual {
        rng.random_range(0.0..0.3) as f32
    } else {
        rng.random_range(0.2..1.5) as f32
    };
    // 6: burst_score — typical low; flash crowds genuinely burst.
    features[6] = if unusual {
        rng.random_range(2.0..15.0) as f32
    } else {
        rng.random_range(0.05..2.0) as f32
    };
    // 7: path_repetition — typical low; polling clients hammer one endpoint.
    features[7] = if unusual {
        rng.random_range(0.5..0.95) as f32
    } else {
        rng.random_range(0.05..0.5) as f32
    };
    // 8: avg_content_length — reasonable.
    features[8] = rng.random_range(0.0..2000.0) as f32;
    // 9: unique_user_agents — typical 1-3; some legitimate proxy fleets rotate UAs.
    features[9] = if unusual {
        rng.random_range(3.0..8.0) as f32
    } else {
        rng.random_range(1.0..4.0) as f32
    };
    // 10: cookie_ratio — typical high; privacy-mode / fresh-visit users have none.
    features[10] = if unusual {
        rng.random_range(0.0..0.4) as f32
    } else {
        rng.random_range(0.5..1.0) as f32
    };
    // 11: referer_ratio — typical moderate-high; direct-navigation users have none.
    features[11] = if unusual {
        rng.random_range(0.0..0.3) as f32
    } else {
        rng.random_range(0.3..1.0) as f32
    };
    // 12: accept_language_ratio — typical high; some API clients omit.
    features[12] = if unusual {
        rng.random_range(0.0..0.4) as f32
    } else {
        rng.random_range(0.5..1.0) as f32
    };
    // 13: suspicious_path_ratio — typical near-zero; misconfigured pages can trigger false positives.
    features[13] = if unusual {
        rng.random_range(0.0..0.25) as f32
    } else {
        rng.random_range(0.0..0.05) as f32
    };

    features
}

/// Generate synthetic scanner training samples.
///
/// Attack samples use paths from wordlist files (if provided) or built-in
/// scanner paths.  Normal samples have realistic browser-like feature vectors.
///
/// Produces 12-dimensional feature vectors matching `NUM_SCANNER_FEATURES`:
///   0: suspicious_path_score, 1: path_depth, 2: has_suspicious_extension,
///   3: has_cookies, 4: has_referer, 5: has_accept_language,
///   6: accept_quality, 7: ua_category, 8: method_is_unusual,
///   9: host_is_configured, 10: content_length_mismatch, 11: path_has_traversal
pub fn generate_scanner_samples(
    wordlist_dir: Option<&Path>,
    _production_logs: Option<&Path>,
    config: &SyntheticConfig,
) -> Result<Vec<TrainingSample>> {
    let mut rng = StdRng::seed_from_u64(config.seed.wrapping_add(1));
    let mut samples = Vec::with_capacity(config.num_scanner_attack + config.num_scanner_normal);

    // Load wordlist paths if provided.
    let attack_paths = load_wordlist_paths(wordlist_dir)?;

    // Generate attack samples.
    for i in 0..config.num_scanner_attack {
        let features = if !attack_paths.is_empty() {
            let path = &attack_paths[i % attack_paths.len()];
            generate_scanner_attack_features_from_path(path, &mut rng)
        } else {
            generate_scanner_attack_features(&mut rng)
        };
        samples.push(TrainingSample {
            features,
            label: 1.0,
            source: DataSource::SyntheticWordlist,
            weight: 0.5,
        });
    }

    // Generate normal samples.
    for _ in 0..config.num_scanner_normal {
        let features = generate_scanner_normal_features(&mut rng);
        samples.push(TrainingSample {
            features,
            label: 0.0,
            source: DataSource::SyntheticWordlist,
            weight: 0.5,
        });
    }

    Ok(samples)
}

/// Load paths from wordlist files in a directory (or single file).
fn load_wordlist_paths(dir: Option<&Path>) -> Result<Vec<String>> {
    let dir = match dir {
        Some(d) => d,
        None => return Ok(Vec::new()),
    };

    let files: Vec<std::path::PathBuf> = if dir.is_file() {
        vec![dir.to_path_buf()]
    } else if dir.exists() {
        std::fs::read_dir(dir)?
            .filter_map(|e| e.ok())
            .map(|e| e.path())
            .filter(|p| p.extension().map(|e| e == "txt").unwrap_or(false))
            .collect()
    } else {
        return Ok(Vec::new());
    };

    let mut paths = Vec::new();
    for file in &files {
        let f = std::fs::File::open(file)?;
        let reader = std::io::BufReader::new(f);
        for line in reader.lines() {
            let line = line?;
            let line = line.trim().to_string();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let normalized = if line.starts_with('/') {
                line
            } else {
                format!("/{line}")
            };
            paths.push(normalized);
        }
    }
    Ok(paths)
}

/// Generate scanner attack features from a specific path.
fn generate_scanner_attack_features_from_path(path: &str, rng: &mut StdRng) -> Vec<f32> {
    let mut features = vec![0.0f32; NUM_SCANNER_FEATURES];

    let lower = path.to_ascii_lowercase();

    // 0: suspicious_path_score — check for known bad fragments.
    let suspicious_frags = [
        ".env", "wp-admin", "wp-login", "phpinfo", "phpmyadmin",
        ".git", "cgi-bin", "shell", "admin", "config",
    ];
    let segments: Vec<&str> = path.split('/').filter(|s| !s.is_empty()).collect();
    let seg_count = segments.len().max(1) as f32;
    let matches = segments
        .iter()
        .filter(|s| {
            let sl = s.to_ascii_lowercase();
            suspicious_frags.iter().any(|f| sl.contains(f))
        })
        .count() as f32;
    features[0] = matches / seg_count;

    // 1: path_depth.
    features[1] = path.bytes().filter(|&b| b == b'/').count().min(20) as f32;

    // 2: has_suspicious_extension.
    let suspicious_exts = [".php", ".env", ".sql", ".bak", ".asp", ".jsp", ".cgi", ".tar", ".zip", ".git"];
    features[2] = if suspicious_exts.iter().any(|e| lower.ends_with(e)) {
        1.0
    } else {
        0.0
    };

    // 15% of scanner attacks mimic browser-like headers (stealthy scanners,
    // headless-chrome / Selenium-based crawlers, captcha-solver bots).
    let stealthy = rng.random_bool(0.15);

    // 3: has_cookies — typical scanners don't; stealthy ones replay sessions.
    features[3] = if stealthy { 1.0 } else if rng.random_bool(0.05) { 1.0 } else { 0.0 };

    // 4: has_referer — typical scanners no referer; stealthy ones forge it.
    features[4] = if stealthy { 1.0 } else if rng.random_bool(0.05) { 1.0 } else { 0.0 };

    // 5: has_accept_language — typical scanners omit; stealthy ones send it.
    features[5] = if stealthy { 1.0 } else if rng.random_bool(0.1) { 1.0 } else { 0.0 };

    // 6: accept_quality — typical 0 (*/* or empty); stealthy 1 (browser-like).
    features[6] = if stealthy { 1.0 } else { 0.0 };

    // 7: ua_category — typical bot UAs; stealthy ones spoof browser.
    let ua_roll: f64 = rng.random();
    features[7] = if stealthy {
        1.0 // browser-like UA
    } else if ua_roll < 0.3 {
        0.0 // empty
    } else if ua_roll < 0.6 {
        0.25 // curl/wget
    } else {
        0.5 // random bot
    };

    // 8: method_is_unusual — mostly GET; advanced scanners try DELETE/PATCH probes.
    features[8] = if stealthy && rng.random_bool(0.3) { 1.0 }
                  else if rng.random_bool(0.05) { 1.0 } else { 0.0 };

    // 9: host_is_configured — typical scanners hit unknown host; some target known ones.
    features[9] = if stealthy { 1.0 } else if rng.random_bool(0.2) { 1.0 } else { 0.0 };

    // 10: content_length_mismatch — keep low; scanners rarely abuse content-length.
    features[10] = if rng.random_bool(0.1) { 1.0 } else { 0.0 };

    // 11: path_has_traversal — derived from the actual path.
    let traversal_patterns = ["..", "%00", "%0a", "%27", "%3c"];
    features[11] = if traversal_patterns.iter().any(|p| lower.contains(p)) {
        1.0
    } else {
        0.0
    };

    features
}

/// Generate scanner attack features without a specific path (built-in defaults).
/// 15% stealthy minority mimics browser-like header signatures, overlapping
/// the legitimate-traffic distribution.
fn generate_scanner_attack_features(rng: &mut StdRng) -> Vec<f32> {
    let mut features = vec![0.0f32; NUM_SCANNER_FEATURES];
    let stealthy = rng.random_bool(0.15);

    // Typical attacks score high on suspicious_path; stealthy ones target legit-looking paths.
    features[0] = if stealthy {
        rng.random_range(0.0..0.3) as f32
    } else {
        rng.random_range(0.3..1.0) as f32
    };
    features[1] = rng.random_range(2.0..8.0) as f32;
    features[2] = if stealthy { 0.0 } else if rng.random_bool(0.6) { 1.0 } else { 0.0 };
    features[3] = if stealthy { 1.0 } else if rng.random_bool(0.05) { 1.0 } else { 0.0 };
    features[4] = if stealthy { 1.0 } else if rng.random_bool(0.05) { 1.0 } else { 0.0 };
    features[5] = if stealthy { 1.0 } else if rng.random_bool(0.1) { 1.0 } else { 0.0 };
    features[6] = if stealthy { 1.0 } else { 0.0 };
    features[7] = if stealthy { 1.0 } else { rng.random_range(0.0..0.5) as f32 };
    features[8] = if rng.random_bool(0.1) { 1.0 } else { 0.0 };
    features[9] = if stealthy { 1.0 } else if rng.random_bool(0.2) { 1.0 } else { 0.0 };
    features[10] = if rng.random_bool(0.1) { 1.0 } else { 0.0 };
    features[11] = if rng.random_bool(0.15) { 1.0 } else { 0.0 };

    features
}

/// Generate normal scanner features (browser-like).
/// 10% unusual minority: mobile apps, API clients, dev tools, captive
/// portals, or genuinely-misconfigured users whose headers look bot-ish.
fn generate_scanner_normal_features(rng: &mut StdRng) -> Vec<f32> {
    let mut features = vec![0.0f32; NUM_SCANNER_FEATURES];
    let unusual = rng.random_bool(0.1);

    // Most normal traffic hits clean paths; some legit requests hit paths
    // that incidentally match a suspicious fragment (e.g. /admin pages).
    features[0] = if unusual { rng.random_range(0.0..0.3) as f32 } else { 0.0 };
    features[1] = rng.random_range(1.0..4.0) as f32;
    features[2] = 0.0;
    features[3] = if unusual { 0.0 } else if rng.random_bool(0.85) { 1.0 } else { 0.0 };
    features[4] = if unusual { 0.0 } else if rng.random_bool(0.7) { 1.0 } else { 0.0 };
    features[5] = if unusual { 0.0 } else if rng.random_bool(0.9) { 1.0 } else { 0.0 };
    features[6] = if unusual { 0.0 } else { 1.0 };
    features[7] = if unusual { rng.random_range(0.0..0.5) as f32 } else { 1.0 };
    features[8] = 0.0;
    features[9] = if rng.random_bool(0.95) { 1.0 } else { 0.0 };
    features[10] = 0.0;
    features[11] = 0.0;

    features
}

/// Sample from a normal distribution, clamped to positive values.
fn sample_positive_normal(rng: &mut StdRng, mean: f64, std_dev: f64) -> f64 {
    if std_dev <= 0.0 {
        return mean.max(0.0);
    }
    // Box-Muller transform.
    let u1: f64 = rng.random::<f64>().max(1e-10);
    let u2: f64 = rng.random();
    let z = (-2.0 * u1.ln()).sqrt() * (2.0 * std::f64::consts::PI * u2).cos();
    (mean + std_dev * z).max(0.0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_ddos_feature_dimensions() {
        let profiles = vec![TimingProfile {
            attack_type: "DDoS".to_string(),
            inter_arrival_mean: 0.01,
            inter_arrival_std: 0.005,
            burst_duration_mean: 2.0,
            burst_duration_std: 1.0,
            flow_bytes_per_sec_mean: 50000.0,
            flow_bytes_per_sec_std: 20000.0,
            sample_count: 100,
        }];

        let config = SyntheticConfig {
            num_ddos_attack: 10,
            num_ddos_normal: 10,
            seed: 42,
            ..Default::default()
        };

        let samples = generate_ddos_samples(&profiles, &config);
        assert_eq!(samples.len(), 20);
        for s in &samples {
            assert_eq!(
                s.features.len(),
                NUM_FEATURES,
                "DDoS features should have {} dimensions",
                NUM_FEATURES
            );
        }
    }

    #[test]
    fn test_scanner_feature_dimensions() {
        let config = SyntheticConfig {
            num_scanner_attack: 10,
            num_scanner_normal: 10,
            seed: 42,
            ..Default::default()
        };

        let samples = generate_scanner_samples(None, None, &config).unwrap();
        assert_eq!(samples.len(), 20);
        for s in &samples {
            assert_eq!(
                s.features.len(),
                NUM_SCANNER_FEATURES,
                "scanner features should have {} dimensions",
                NUM_SCANNER_FEATURES
            );
        }
    }

    #[test]
    fn test_deterministic_with_fixed_seed() {
        let config = SyntheticConfig {
            num_ddos_attack: 5,
            num_ddos_normal: 5,
            num_scanner_attack: 5,
            num_scanner_normal: 5,
            seed: 123,
        };

        let ddos_a = generate_ddos_samples(&[], &config);
        let ddos_b = generate_ddos_samples(&[], &config);

        for (a, b) in ddos_a.iter().zip(ddos_b.iter()) {
            assert_eq!(a.features, b.features, "DDoS samples should be deterministic");
            assert_eq!(a.label, b.label);
        }

        let scanner_a = generate_scanner_samples(None, None, &config).unwrap();
        let scanner_b = generate_scanner_samples(None, None, &config).unwrap();

        for (a, b) in scanner_a.iter().zip(scanner_b.iter()) {
            assert_eq!(a.features, b.features, "scanner samples should be deterministic");
            assert_eq!(a.label, b.label);
        }
    }

    #[test]
    fn test_ddos_attack_vs_normal_distinguishable() {
        let config = SyntheticConfig {
            num_ddos_attack: 100,
            num_ddos_normal: 100,
            seed: 42,
            ..Default::default()
        };

        let samples = generate_ddos_samples(&[], &config);
        let attacks: Vec<&TrainingSample> = samples.iter().filter(|s| s.label > 0.5).collect();
        let normals: Vec<&TrainingSample> = samples.iter().filter(|s| s.label <= 0.5).collect();

        // Attack samples should have higher avg request_rate (feature 0).
        let avg_attack_rate: f32 =
            attacks.iter().map(|s| s.features[0]).sum::<f32>() / attacks.len() as f32;
        let avg_normal_rate: f32 =
            normals.iter().map(|s| s.features[0]).sum::<f32>() / normals.len() as f32;
        assert!(
            avg_attack_rate > avg_normal_rate,
            "attack rate {} should exceed normal rate {}",
            avg_attack_rate,
            avg_normal_rate
        );

        // Attack samples should have lower avg cookie_ratio (feature 10).
        let avg_attack_cookies: f32 =
            attacks.iter().map(|s| s.features[10]).sum::<f32>() / attacks.len() as f32;
        let avg_normal_cookies: f32 =
            normals.iter().map(|s| s.features[10]).sum::<f32>() / normals.len() as f32;
        assert!(
            avg_attack_cookies < avg_normal_cookies,
            "attack cookies {} should be lower than normal cookies {}",
            avg_attack_cookies,
            avg_normal_cookies
        );
    }

    #[test]
    fn test_sample_positive_normal_stays_positive() {
        let mut rng = StdRng::seed_from_u64(42);
        for _ in 0..1000 {
            let val = sample_positive_normal(&mut rng, 1.0, 5.0);
            assert!(val >= 0.0, "value should be non-negative: {val}");
        }
    }

    #[test]
    fn test_scanner_attack_from_wordlist_path() {
        let mut rng = StdRng::seed_from_u64(42);
        let features = generate_scanner_attack_features_from_path("/.env", &mut rng);
        assert_eq!(features.len(), NUM_SCANNER_FEATURES);
        // .env should trigger suspicious_path_score > 0.
        assert!(features[0] > 0.0, "suspicious_path_score should be positive for /.env");
        // .env should trigger suspicious_extension.
        assert_eq!(features[2], 1.0, "should detect .env as suspicious extension");
    }
}
